with ranked as (select *, row_number() over (partition by order_id, product_id order by unit_price desc, id) as latest_rank from order_items qualify latest_rank = 1), base as (select id, order_id, quantity, unit_price, latest_rank, latest_rank * unit_price as latest_rank_times_unit_price from ranked where product_id in (12, 13)), with_dims as (select s.*, d.channel, d.order_date, d.shipping_fee from base s left join orders d on s.order_id = d.id), attributed as (select s.*, pr.id as promo_id, pr.promo_code, pr.discount_pct from with_dims s left join promotions pr on s.channel = pr.channel and s.order_date >= pr.starts_on and s.order_date < pr.ends_on + interval '30' day), scored as (select id, quantity, latest_rank, latest_rank_times_unit_price, order_date, shipping_fee, promo_id, max(unit_price) over w_recent as last7_max_unit_price, min(unit_price) over w_recent as last7_min_unit_price, sum(unit_price) over w_recent as last7_sum_unit_price, count(unit_price) over w_recent as last7_count_unit_price, last_value(latest_rank_times_unit_price) ignore nulls over (partition by promo_code order by promo_id, id, promo_id rows between unbounded preceding and current row) as last_known_latest_rank_times_unit_price from attributed where latest_rank_times_unit_price < 43 window w_recent as (partition by order_id order by shipping_fee, id, promo_id rows between 6 preceding and current row)), grouped as (select promo_id, bit_and(quantity) as quantity_bit_and, round(avg(promo_id), 2) as avg_promo_id, min(last_known_latest_rank_times_unit_price) as min_last_known_latest_rank_times_unit_price, avg(last_known_latest_rank_times_unit_price) as avg_last_known_latest_rank_times_unit_price from scored group by 1) select promo_id, quantity_bit_and, avg_promo_id, min_last_known_latest_rank_times_unit_price, avg_last_known_latest_rank_times_unit_price from grouped;
